// <auto-generated/>

using System;
using Enterprise.Core;
using Enterprise.Freight.Business.Extensions;
using Enterprise.Freight.Forwarding.Business;
using Enterprise.MasterFiles.Business;
using Enterprise.TransportBookings.Shared;
using Enterprise.TransportCommon.Shared;
using Enterprise.ZArchitecture.GUI;
using Enterprise.ZArchitecture.Modules;

namespace Enterprise.Freight.Forwarding.GUI
{
	public partial class ShipmentPickupDetailsControl : ZUserControl
	{
		public ShipmentPickupDetailsControl(IDtbBookingParent bookingParent)
		{
			InitializeComponent();
			InitializeAdditionalCaptions();

			ContainerTabControl.PlugIns.AddPlugInAtTabPageIndex(ControllerIDs.DtbBookingTabPlugIn, 0, () => new BookingDirectionSelection(bookingParent, DtbBookingDirection.PIC));
		}

		void InitializeAdditionalCaptions()
		{
			this.PickupCartageCoGroupBox.Text = Res.GetString("Forwarding|ShipmentDeliveryDetailsControl|PickupCartageCompany", "Pickup Transport Company");

			ACIConsignorOriginZoneLabel.Visible = (GlbCompany.CurrentCompany.GC_RN_NKCountryCode == Core.Constants.CountryCodes.UnitedStates || GlbCompany.CurrentCompany.GC_RN_NKCountryCode == Core.Constants.CountryCodes.Canada);
		}

		#region Binding

		protected override void OnCurrentDataItemChanging(EventArgs e)
		{
			base.OnCurrentDataItemChanging(e);
			if (Shipment != null)
			{
				Shipment.JS_TransportModeInfo.ValueChanged -= TransportModePackingModeChanged;
				Shipment.JS_PackingModeInfo.ValueChanged -= TransportModePackingModeChanged;
			}
		}

		protected override void OnCurrentDataItemChanged(EventArgs e)
		{
			base.OnCurrentDataItemChanged(e);
			if (Shipment != null)
			{
				Shipment.JS_PackingModeInfo.ValueChanged += TransportModePackingModeChanged;
				Shipment.JS_TransportModeInfo.ValueChanged += TransportModePackingModeChanged;
				ShowPenaltyControls();

				Shipment.JS_TransportModeInfo.ValueChanged += TransportModeChanged;
				ResetShipmentStatus();
			}
		}

		#endregion

		#region Show / Hide controls

		void TransportModePackingModeChanged(object sender, EventArgs e)
		{
			ShowPenaltyControls();
		}

		void ShowPenaltyControls()
		{
			var isLCL = Shipment != null && (Shipment.IsAir || Constants.ContainerModes.IsLCLType(Shipment.JS_PackingMode));
			FreeLabel.Visible = !isLCL;
			DetentionFreeDaysCalcEdit.Visible = !isLCL;
			DetentionDaysLabel.Visible = !isLCL;
			DetentionDaysCalcEdit.Visible = !isLCL;
			DetentionChargeCalcEdit.Visible = !isLCL;
			DetentionLabel.Visible = !isLCL;

			ShowPenaltyControlsIfShipmentPenaltyEnabled();
		}

		void ShowPenaltyControlsIfShipmentPenaltyEnabled()
		{
			var showPenaltyGrid = Shipment.IsShipmentPickupPenaltyApplicable();

			if (showPenaltyGrid)
			{
				DetentionFreeDaysCalcEdit.Visible = true;
				DetentionDaysLabel.Visible = true;
				DetentionDaysCalcEdit.Visible = true;
				DetentionChargeCalcEdit.Visible = true;
				DetentionLabel.Visible = true;
			}

			PickupPenaltiesTabPage.TabVisible = showPenaltyGrid;
		}

		void TransportModeChanged(object sender, EventArgs e)
		{
			ResetShipmentStatus();
		}

		void ResetShipmentStatus()
		{
			var isSea = Shipment != null && Shipment.JS_TransportMode == Constants.TransportModes.Sea;
			ShipmentStatusDropEdit.Visible = isSea;
		}

		#endregion

		#region Shipment

		ForwardingShipment Shipment => CurrentDataItem as ForwardingShipment;

		#endregion
	}
}
